     1	import { CONFIG } from '../config';
     2	
     3	/* ============================ Địa hình núi: hàm độ cao (D-047) ============================
     4	   Thuần số học, không three, không rand(): nhiễu băm số nguyên nên tất định và không đụng chuỗi seed chung.
     5	   Mỗi khối núi là vài "sống núi" (đường gấp khúc có độ cao + bề rộng sườn tại từng điểm); sườn có dông phụ / khe
     6	   nhờ bề rộng đổi dọc sống và nhiễu sống đã vặn miền. Bán đảo Sơn Trà giữ vị trí các hình nón cũ:
     7	   đỉnh chính (2600, −4700) ≈ 690 m (thật 696 m), nhánh Đông Nam quanh (3300, −3100), đồi thấp phía Tây quanh (1750, −4350). */
     8	
     9	const T = CONFIG.sonTra;
    10	export interface Box { x0: number; x1: number; z0: number; z1: number }
    11	export const ST_BOX: Box = { x0: 560, x1: 6500, z0: -6700, z1: -1750 };     // m — khung lấy mẫu Sơn Trà
    12	export const HV_BOX: Box = { x0: -11200, x1: 1700, z0: -10800, z1: -3300 }; // m — khung lấy mẫu dãy Hải Vân
    13	
    14	/* ---- nhiễu ---- */
    15	const hash = (ix: number, iz: number) => { let h = Math.imul(ix, 374761393) ^ Math.imul(iz, 668265263); h = Math.imul(h ^ (h >>> 13), 1274126177); return ((h ^ (h >>> 16)) >>> 0) / 4294967296; };
    16	/** Nhiễu giá trị 2D mượt, 0..1, chu kỳ ô = 1 đơn vị. */
    17	export function stNoise(x: number, z: number) {
    18	  const ix = Math.floor(x), iz = Math.floor(z), fx = x - ix, fz = z - iz, u = fx * fx * (3 - 2 * fx), v = fz * fz * (3 - 2 * fz);
    19	  const a = hash(ix, iz), b = hash(ix + 1, iz), c = hash(ix, iz + 1), d = hash(ix + 1, iz + 1);
    20	  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
    21	}
    22	export function stFbm(x: number, z: number, oct = 4) { let s = 0, a = 0.5, n = 0; for (let i = 0; i < oct; i++) { s += a * stNoise(x, z); n += a; a *= 0.5; x = x * 2.03 + 17.3; z = z * 2.03 - 9.1; } return s / n; }
    23	/** Nhiễu sống: 1 ở "sống", 0 ở "khe". */
    24	function ridged(x: number, z: number, oct = 3) { let s = 0, a = 0.5, n = 0; for (let i = 0; i < oct; i++) { const r = 1 - Math.abs(2 * stNoise(x, z) - 1); s += a * r * r; n += a; a *= 0.5; x = x * 2.1 + 5.7; z = z * 2.1 + 13.9; } return s / n; }
    25	const sat = (t: number) => (t < 0 ? 0 : t > 1 ? 1 : t), sstep = (a: number, b: number, t: number) => { t = sat((t - a) / (b - a)); return t * t * (3 - 2 * t); };
    26	const smax = (a: number, b: number, k: number) => { const h = Math.max(k - Math.abs(a - b), 0) / k; return Math.max(a, b) + h * h * k * 0.25; };
    27	
    28	/* ---- sống núi: [x, z, cao (m), bề rộng sườn (m)] ---- */
    29	type Pt = [number, number, number, number];
    30	const ST_SPINES: Pt[][] = [
    31	  // sống chính Tây → Đông: đồi thấp phía Tiên Sa, vai Tây, đỉnh ra-đa rộng, yên ngựa, hai đỉnh phía Đông rồi hạ xuống mũi
    32	  [[1230, -4260, 130, 500], [1640, -4420, 330, 740], [2060, -4630, 520, 940], [2370, -4700, 650, 1150], [2600, -4700, 696, 1240], [2840, -4680, 664, 1200], [3110, -4640, 585, 1120], [3520, -4540, 640, 1160], [4010, -4370, 500, 1040], [4520, -4160, 556, 1020], [5020, -3910, 380, 880], [5500, -3660, 240, 680], [5880, -3470, 70, 420]],
    33	  // dông phía Bắc xuống biển
    34	  [[2600, -4700, 696, 1240], [2520, -5330, 390, 760], [2380, -5850, 170, 520]],
    35	  [[3520, -4540, 640, 1160], [3720, -5180, 330, 700], [3830, -5650, 130, 460]],
    36	  // nhánh Đông Nam (chỗ hình nón thứ hai cũ), hạ dần về phía Mỹ Khê
    37	  [[3520, -4540, 600, 900], [3420, -3900, 385, 800], [3300, -3220, 468, 860], [3250, -2640, 250, 640], [3210, -2230, 60, 360]],
    38	  // dông Tây Nam từ đỉnh chính xuống phía thành phố
    39	  [[2600, -4700, 696, 1240], [2330, -4160, 380, 700], [2120, -3760, 150, 480]]
    40	];
    41	const HV_SPINES: Pt[][] = [
    42	  [[-10400, -5300, 380, 1500], [-8600, -5350, 640, 1900], [-7000, -5650, 930, 2150], [-5600, -6150, 760, 1900], [-4200, -6600, 1100, 2400], [-3200, -7050, 800, 1950], [-2300, -7500, 705, 1750], [-1100, -8000, 420, 1350], [100, -8500, 190, 900]],
    43	  [[-4200, -6600, 1100, 2400], [-4500, -8100, 720, 1800], [-5200, -9500, 420, 1300]],
    44	  [[-7000, -5650, 930, 2150], [-7600, -7400, 640, 1700]]
    45	];
    46	
    47	/* Độ cao thô của một sống tại (x, z): mặt cắt sườn lõm, đỉnh sống bo nhẹ. Bề rộng sườn đổi theo "tọa độ vòng quanh sống"
    48	   (đi dọc sườn bên này, vòng qua mũi, về theo sườn bên kia, vòng qua gốc: liền mạch, nhiễu lấy trên đường tròn nên khép kín)
    49	   ⇒ dông phụ và khe chạy từ sống xuống chân như núi bị xói, không phải gò tròn. */
    50	const ridge1 = (n: number) => { const r = 1 - Math.abs(2 * n - 1); return r * r; };
    51	const sD = new Float64Array(16), sH = new Float64Array(16), sW = new Float64Array(16), sS = new Float64Array(16);   // vùng nhớ tạm theo đoạn sống (≤ 16 đoạn)
    52	function spineH(pts: Pt[], x: number, z: number, seed: number) {
    53	  let best = 1e18, side = 1, acc = 0, seg = 0, tt = 0;
    54	  const m = pts.length - 1;
    55	  for (let i = 0; i < m; i++) {
    56	    const a = pts[i], b = pts[i + 1], dx = b[0] - a[0], dz = b[1] - a[1], L2 = dx * dx + dz * dz, L = Math.sqrt(L2);
    57	    const t = sat(((x - a[0]) * dx + (z - a[1]) * dz) / L2), px = a[0] + dx * t, pz = a[1] + dz * t, d2 = (x - px) * (x - px) + (z - pz) * (z - pz), s = t * t * (3 - 2 * t);
    58	    sD[i] = Math.sqrt(d2); sH[i] = a[2] + (b[2] - a[2]) * s; sW[i] = a[3] + (b[3] - a[3]) * s; sS[i] = acc + t * L;
    59	    if (d2 < best) { best = d2; side = dx * (z - a[1]) - dz * (x - a[0]) > 0 ? 1 : -1; seg = i; tt = t; }
    60	    acc += L;
    61	  }
    62	  // H, W, S trộn mượt giữa các đoạn gần ngang nhau: ở phía lõm của chỗ sống đổi hướng, điểm gần nhất nhảy từ đoạn này sang đoạn kia, không trộn thì thành vách thẳng
    63	  const d = Math.sqrt(best), tau = 30 + 0.22 * d; let H = 0, W = 0, S = 0, ws = 0;
    64	  for (let i = 0; i < m; i++) { const w = Math.exp(-(sD[i] - d) / tau); if (w < 1e-4) continue; H += w * sH[i]; W += w * sW[i]; S += w * sS[i]; ws += w; }
    65	  H /= ws; W /= ws; S /= ws;
    66	  if (d >= W * (1 + T.spurAmp)) return 0;
    67	  // tọa độ vòng quanh sống c ∈ [0, C)
    68	  const n = pts.length, Re = pts[n - 1][3] * 0.55, Rs = pts[0][3] * 0.55, C = 2 * acc + Math.PI * (Re + Rs);
    69	  let c: number;
    70	  if (seg === n - 2 && tt >= 1) { const a = pts[n - 2], b = pts[n - 1], dx = b[0] - a[0], dz = b[1] - a[1]; c = acc + (Math.PI / 2 - Math.atan2(dx * (z - b[1]) - dz * (x - b[0]), dx * (x - b[0]) + dz * (z - b[1]))) * Re; }
    71	  else if (seg === 0 && tt <= 0) { const a = pts[0], b = pts[1], dx = a[0] - b[0], dz = a[1] - b[1]; c = 2 * acc + Math.PI * Re + (Math.PI / 2 - Math.atan2(dx * (z - a[1]) - dz * (x - a[0]), dx * (x - a[0]) + dz * (z - a[1]))) * Rs; }
    72	  else c = side > 0 ? S : 2 * acc + Math.PI * Re - S;
    73	  const ang = c / C * Math.PI * 2, ca = Math.cos(ang), sa = Math.sin(ang), per = (len: number, o: number) => { const r = C / (Math.PI * 2 * len); return stNoise(o + r * ca, o * 1.7 + 3.3 + r * sa); };
    74	  const o = seed * 9.1 + 20;
    75	  const fine = 1 - 0.8 * sat(d / W);   // khe mịn nhạt dần về chân: độ lệch tỉ lệ với khoảng cách tới sống, để nguyên thì chân núi thành nếp gấp dốc đứng
    76	  const lobe = per(T.spurLen, o) * 0.52 + (ridge1(per(T.spurLen * 0.42, o + 40)) * 0.34 + ridge1(per(T.spurLen * 0.23, o + 80)) * 0.14) * fine + 0.16 * (1 - fine);
    77	  const w = W * (1 - T.spurAmp + 2 * T.spurAmp * lobe), r0 = T.crestRound * W;
    78	  const u = (Math.sqrt(d * d + r0 * r0) - r0) / w;
    79	  if (u >= 1) return 0;
    80	  const crest = 1 - T.crestVar * (1 - stNoise(S / T.crestLen + seed * 3.7, seed + 7.7));   // đường sống nhấp nhô
    81	  return H * crest * Math.pow(1 - u, T.slopePow) * (1 - T.footEase * u * u);
    82	}
    83	function massif(spines: Pt[][], x: number, z: number, seed: number) {
    84	  // vặn miền để dông / đường bờ không thẳng
    85	  let wx = x + (stFbm(x / T.warpLen + seed, z / T.warpLen - seed, 3) - 0.5) * 2 * T.warpAmp, wz = z + (stFbm(x / T.warpLen - 31.7, z / T.warpLen + 12.9 + seed, 3) - 0.5) * 2 * T.warpAmp;
    86	  wx += (stNoise(x / T.warp2Len + 91.3, z / T.warp2Len + seed) - 0.5) * 2 * T.warp2Amp; wz += (stNoise(x / T.warp2Len - 44.1, z / T.warp2Len - 3 * seed) - 0.5) * 2 * T.warp2Amp;   // vặn nhỏ: khe không song song đều nhau
    87	  let h = 0;
    88	  for (let i = 0; i < spines.length; i++) { const s = spineH(spines[i], wx, wz, seed + i * 11), k = Math.min(T.blend, Math.min(h, s) * 1.5); h = k > 1e-3 ? smax(h, s, k) : Math.max(h, s); }   // độ mượt co về 0 ở chân để không đội nền lên
    89	  if (h <= 0) return -T.seaDrop;
    90	  // khe xói: nhiễu sống khoét lưng chừng sườn (không khoét đỉnh sống, không khoét chân)
    91	  const mid = sat(h / 140) * (1 - T.gullyCrest * sat(h / 700));
    92	  const g = ridged(wx / T.gullyLen + seed * 1.7, wz / T.gullyLen - seed * 2.3, 3);
    93	  h *= 1 - T.gullyAmp * (1 - g) * mid;
    94	  // gồ ghề nhỏ + đường bờ lệch
    95	  h += (stFbm(x / T.bumpLen + seed, z / T.bumpLen, 3) - 0.5) * 2 * T.bumpAmp * sat(h / 90);
    96	  return h - T.seaDrop * (1 - sat(h / 110)) - (stFbm(x / 620 - seed, z / 620 + seed, 2) - 0.35) * T.coastAmp * (1 - sat(h / 70));
    97	}
    98	
    99	/** 0 trong vùng đất liền bờ Đông (đất, đường, nhà quanh đầu Đông Cầu Thuận Phước), tăng tới 1 khi ra xa `keepRamp` m. */
   100	export function stLandMask(x: number, z: number) { const dx = Math.max(0, x - T.keepX), dz = Math.max(0, T.keepZ - z); return sstep(0, T.keepRamp, Math.hypot(dx, dz)); }
   101	
   102	/** Độ cao Sơn Trà (m, so với mặt nước y = 0; âm = chìm). Trong vùng đất liền núi bị ép dưới mặt đất. */
   103	export function stHeight(x: number, z: number) {
   104	  const raw = massif(ST_SPINES, x, z, 1), m = stLandMask(x, z);
   105	  return m >= 1 ? raw : m * raw + (1 - m) * Math.min(T.keepY, raw);
   106	}
   107	/** Độ cao dãy Hải Vân (m). Hạ về 0 trước mép đất bờ Tây (z > −3900). */
   108	export function hvHeight(x: number, z: number) { const raw = massif(HV_SPINES, x, z, 5); return raw <= 0 ? raw : raw * sstep(-3450, -4300, z) - (1 - sstep(-3450, -4300, z)) * T.seaDrop; }
   109	import * as THREE from 'three';
   110	import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
   111	import { CONFIG } from '../config';
   112	import { stHeight, hvHeight, stFbm, stNoise, stLandMask, ST_BOX, HV_BOX, type Box } from './terrain';
   113	
   114	/* ============================ Lưới núi Sơn Trà + Hải Vân (D-047) ============================
   115	   Lấy mẫu hàm độ cao trên lưới đều, bỏ ô chìm, pháp tuyến mượt từ sai phân, màu đỉnh nướng sẵn
   116	   (sắc rừng, độ khuất khe / thung lũng, đá ở dốc đứng và mép nước). Không cần renderer nên test node gọi được. */
   117	
   118	const T = CONFIG.sonTra;
   119	const sat = (t: number) => (t < 0 ? 0 : t > 1 ? 1 : t), sstep = (a: number, b: number, t: number) => { t = sat((t - a) / (b - a)); return t * t * (3 - 2 * t); };
   120	
   121	/* Trung bình hộp bán kính r ô (hai lượt tách trục) */
   122	function blur(src: Float32Array, nx: number, nz: number, r: number) {
   123	  const tmp = new Float32Array(src.length), out = new Float32Array(src.length);
   124	  for (let j = 0; j < nz; j++) for (let i = 0; i < nx; i++) { let s = 0, n = 0; for (let k = Math.max(0, i - r); k <= Math.min(nx - 1, i + r); k++) { s += src[j * nx + k]; n++; } tmp[j * nx + i] = s / n; }
   125	  for (let j = 0; j < nz; j++) for (let i = 0; i < nx; i++) { let s = 0, n = 0; for (let k = Math.max(0, j - r); k <= Math.min(nz - 1, j + r); k++) { s += tmp[k * nx + i]; n++; } out[j * nx + i] = s / n; }
   126	  return out;
   127	}
   128	
   129	function field(hf: (x: number, z: number) => number, box: Box, cell: number, landMask: ((x: number, z: number) => number) | null) {
   130	  const nx = Math.round((box.x1 - box.x0) / cell) + 1, nz = Math.round((box.z1 - box.z0) / cell) + 1, N = nx * nz;
   131	  const h = new Float32Array(N);
   132	  for (let j = 0; j < nz; j++) for (let i = 0; i < nx; i++) h[j * nx + i] = hf(box.x0 + i * cell, box.z0 + j * cell);
   133	  const hc = h.map((v) => Math.max(v, 0)), bN = blur(hc, nx, nz, T.aoNear), bF = blur(hc, nx, nz, T.aoFar);
   134	  // ô nào có đỉnh nổi (hoặc sát mặt nước) thì giữ; đánh số lại đỉnh dùng tới
   135	  const idx: number[] = [], map = new Int32Array(N).fill(-1); let used = 0;
   136	  const id = (k: number) => (map[k] < 0 ? (map[k] = used++) : map[k]);
   137	  for (let j = 0; j < nz - 1; j++) for (let i = 0; i < nx - 1; i++) {
   138	    const a = j * nx + i, b = a + 1, c = a + nx, d = c + 1;
   139	    if (Math.max(h[a], h[b], h[c], h[d]) < -3) continue;
   140	    if (landMask && landMask(box.x0 + (i + 0.5) * cell, box.z0 + (j + 0.5) * cell) <= 0 && landMask(box.x0 + i * cell, box.z0 + j * cell) <= 0 && landMask(box.x0 + (i + 1) * cell, box.z0 + (j + 1) * cell) <= 0) continue;   // nằm trọn dưới đất liền
   141	    // chéo đổi chiều theo ô cho đỡ vệt răng cưa một hướng
   142	    if ((i + j) & 1) idx.push(id(a), id(c), id(b), id(b), id(c), id(d)); else idx.push(id(a), id(c), id(d), id(a), id(d), id(b));
   143	  }
   144	  const pos = new Float32Array(used * 3), nor = new Float32Array(used * 3), col = new Float32Array(used * 3), rock = new Float32Array(used);
   145	  const C = (hex: number) => new THREE.Color(hex), cDark = C(T.forestDark), cMid = C(T.forestMid), cLight = C(T.forestLight), cDry = C(T.forestDry), cRock = C(T.rock), cShore = C(T.shore), c = new THREE.Color();
   146	  const H = (i: number, j: number) => h[Math.min(nz - 1, Math.max(0, j)) * nx + Math.min(nx - 1, Math.max(0, i))];
   147	  for (let j = 0; j < nz; j++) for (let i = 0; i < nx; i++) {
   148	    const k = j * nx + i, v = map[k]; if (v < 0) continue;
   149	    const x = box.x0 + i * cell, z = box.z0 + j * cell, y = h[k];
   150	    pos[v * 3] = x; pos[v * 3 + 1] = Math.max(y, -T.seaDrop - 1); pos[v * 3 + 2] = z;
   151	    const gx = (H(i + 1, j) - H(i - 1, j)) / (2 * cell), gz = (H(i, j + 1) - H(i, j - 1)) / (2 * cell), il = 1 / Math.hypot(gx, 1, gz), ny = il;
   152	    nor[v * 3] = -gx * il; nor[v * 3 + 1] = ny; nor[v * 3 + 2] = -gz * il;
   153	    // độ khuất: thấp hơn trung bình lân cận ⇒ khe / thung lũng ⇒ tối; cao hơn ⇒ dông ⇒ sáng
   154	    const conv = ((hc[k] - bN[k]) / (T.aoNear * cell) * 2.2 + (hc[k] - bF[k]) / (T.aoFar * cell) * 1.6) * T.aoGain;
   155	    const ao = Math.min(1.18, Math.max(0.5, 1 + conv));
   156	    // sắc rừng: mảng lớn + dông sáng / khe tối + mảng lá vàng
   157	    const big = stFbm(x / 760 + 3.1, z / 760 - 8.4, 3), patch = stFbm(x / 230 - 11.2, z / 230 + 5.5, 2), ridge = sat(0.5 + conv * 2.4);
   158	    c.copy(cDark).lerp(cMid, sat(0.25 + ridge * 0.9 + (big - 0.5) * 0.8)).lerp(cLight, sat((ridge - 0.45) * 1.1 + (patch - 0.5) * 0.9) * 0.75);
   159	    c.lerp(cDry, sstep(0.62, 0.8, stFbm(x / 420 + 40.7, z / 420 + 2.3, 3)) * 0.5);
   160	    // đá: dốc đứng (bị nhiễu bẻ vụn) và dải mép nước ngoài vùng tiếp đất
   161	    const lm = landMask ? landMask(x, z) : 1, br = stNoise(x / 60, z / 60);
   162	    const rk = sstep(T.rockSlope[0], T.rockSlope[1], ny + (br - 0.5) * 0.1) * 0.85, sh = sstep(T.shoreY[0], T.shoreY[1], y + (br - 0.5) * 5) * sstep(0.25, 0.6, lm);
   163	    c.lerp(cRock, rk).lerp(cShore, sh);
   164	    const sh2 = y < 60 && lm < 1 ? sstep(0.9, 0.1, lm) * 0.25 : 0;   // chân núi sát đất liền: rừng thưa, sáng hơn chút
   165	    c.lerp(cLight, sh2);
   166	    col[v * 3] = c.r * ao; col[v * 3 + 1] = c.g * ao; col[v * 3 + 2] = c.b * ao; rock[v] = Math.max(rk, sh);
   167	  }
   168	  const g = new THREE.BufferGeometry();
   169	  g.setAttribute('position', new THREE.BufferAttribute(pos, 3)); g.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
   170	  g.setAttribute('color', new THREE.BufferAttribute(col, 3)); g.setAttribute('aRock', new THREE.BufferAttribute(rock, 1));
   171	  g.setIndex(idx);
   172	  return g;
   173	}
   174	
   175	/** Một lưới cho cả Sơn Trà (ô `cell`) và Hải Vân (ô `cellFar`): position, normal, color, aRock, có index. */
   176	export function mtGeometry(): THREE.BufferGeometry {
   177	  return mergeGeometries([field(stHeight, ST_BOX, T.cell, stLandMask), field(hvHeight, HV_BOX, T.cellFar, null)]);
   178	}
   179	import * as THREE from 'three';
   180	import { CONFIG } from '../config';
   181	import { rng } from '../common/math';
   182	import { canvasTex } from '../core/textures';
   183	
   184	/* ============================ Vật liệu núi rừng (D-047) ============================
   185	   Màu nền + độ khuất nằm trong màu đỉnh (mountainGeo.ts). Shader thêm vân tán rừng lấy theo tọa độ thế giới xz
   186	   ở ba tỉ lệ (tán cây, cụm tán, mảng sắc độ) từ một texture canvas lát được, và nghiêng pháp tuyến theo vân
   187	   để tán bắt nắng. Mipmap lo phần răng cưa khi nhìn xa. Đá (aRock) thì giảm vân. Sương: scene.fog sẵn có. */
   188	
   189	/* R: độ cao tán (đốm tròn chồng nhau, sáng ở đỉnh tán); G: nhiễu mảng lớn. Vẽ lặp qua mép để lát liền. */
   190	function stCanopyTexture() {
   191	  const S = 512, rnd = rng(47047);
   192	  const t = canvasTex(S, S, (g) => {
   193	    g.fillStyle = '#000'; g.fillRect(0, 0, S, S); g.globalCompositeOperation = 'lighter';
   194	    const blob = (x: number, y: number, r: number, css: string) => {
   195	      for (const ox of [-S, 0, S]) for (const oy of [-S, 0, S]) {
   196	        if (x + ox + r < 0 || x + ox - r > S || y + oy + r < 0 || y + oy - r > S) continue;
   197	        const gr = g.createRadialGradient(x + ox - r * 0.2, y + oy - r * 0.2, 0, x + ox, y + oy, r);
   198	        gr.addColorStop(0, css); gr.addColorStop(1, 'rgba(0,0,0,0)'); g.fillStyle = gr; g.fillRect(x + ox - r, y + oy - r, 2 * r, 2 * r);
   199	      }
   200	    };
   201	    for (let i = 0; i < 1500; i++) blob(rnd() * S, rnd() * S, 7 + rnd() * 13, `rgba(${Math.round(70 + rnd() * 110)},0,0,1)`);   // tán cây
   202	    for (let i = 0; i < 46; i++) blob(rnd() * S, rnd() * S, 40 + rnd() * 90, `rgba(0,${Math.round(40 + rnd() * 70)},0,1)`);      // mảng sắc độ
   203	  });
   204	  t.colorSpace = THREE.NoColorSpace; t.wrapS = t.wrapT = THREE.RepeatWrapping;
   205	  return t;
   206	}
   207	
   208	export function mtMaterial() {
   209	  const T = CONFIG.sonTra, f = (n: number) => n.toFixed(4);
   210	  const m = new THREE.MeshStandardMaterial({ color: 0xffffff, vertexColors: true, roughness: 1, metalness: 0 });
   211	  const uTex = { value: stCanopyTexture() };
   212	  m.customProgramCacheKey = () => 'mountainForest';
   213	  m.onBeforeCompile = (sh) => {
   214	    sh.uniforms.uMtTex = uTex;
   215	    sh.vertexShader = sh.vertexShader
   216	      .replace('#include <common>', '#include <common>\nattribute float aRock;\nvarying vec3 vMtPos;\nvarying float vMtRock;')
   217	      .replace('#include <begin_vertex>', '#include <begin_vertex>\n  vMtPos = (modelMatrix * vec4(transformed, 1.0)).xyz; vMtRock = aRock;');
   218	    sh.fragmentShader = sh.fragmentShader
   219	      .replace('#include <common>', '#include <common>\nuniform sampler2D uMtTex;\nvarying vec3 vMtPos;\nvarying float vMtRock;')
   220	      .replace('#include <color_fragment>', `#include <color_fragment>
   221	  vec2 mtQ = vMtPos.xz; float mtVeg = 1.0 - vMtRock;
   222	  vec2 mtU1 = mtQ / ${f(T.tile[0])}, mtU2 = mtQ.yx / ${f(T.tile[1])} + 0.37;
   223	  float mtC1 = texture2D(uMtTex, mtU1).r, mtC2 = texture2D(uMtTex, mtU2).r, mtC3 = texture2D(uMtTex, mtQ / ${f(T.tile[2])} + 0.11).g;
   224	  float mtCan = mtC2 * 0.62 + mtC1 * 0.38;
   225	  diffuseColor.rgb *= mix(1.0, mix(${f(T.canopyTone[0])}, ${f(T.canopyTone[1])}, smoothstep(0.08, 0.95, mtCan)), mtVeg * 0.9 + 0.1);
   226	  diffuseColor.rgb = mix(diffuseColor.rgb, diffuseColor.rgb * vec3(1.45, 1.2, 0.62), clamp((mtC3 - 0.42) * 2.2, 0.0, 1.0) * ${f(T.hueAmp)} * mtVeg);`)
   227	      .replace('#include <normal_fragment_maps>', `#include <normal_fragment_maps>
   228	  {
   229	    float e2 = 6.0 / ${f(T.tile[1])}, e1 = 1.6 / ${f(T.tile[0])};
   230	    vec2 mtG = vec2(texture2D(uMtTex, mtU2 + vec2(e2, 0.0)).r - mtC2, texture2D(uMtTex, mtU2 + vec2(0.0, e2)).r - mtC2) * 0.62
   231	             + vec2(texture2D(uMtTex, mtU1 + vec2(e1, 0.0)).r - mtC1, texture2D(uMtTex, mtU1 + vec2(0.0, e1)).r - mtC1) * 0.38;
   232	    // mtU2 lấy theo (z, x) nên đổi chỗ gradient của lớp cụm tán: gần đúng là đủ cho vân rừng
   233	    normal = normalize(normal - (viewMatrix * vec4(mtG.x, 0.0, mtG.y, 0.0)).xyz * ${f(T.canopyBump)} * mtVeg);
   234	  }`);
   235	  };
   236	  return m;
   237	}
   238	import * as THREE from 'three';
   239	import { scene } from '../core/renderer';
   240	import { MAT } from '../core/materials';
   241	import { mtGeometry } from './mountainGeo';
   242	
   243	/* Núi Sơn Trà (đông bắc) và dãy Hải Vân (tây bắc) làm đường chân trời.
   244	   D-047: một lưới địa hình liền mạch phủ rừng (hình: terrain.ts, lưới + màu: mountainGeo.ts, vật liệu: mountainMat.ts) thay 7 hình nón cũ; vẫn một lệnh vẽ.
   245	   Không đổ / nhận bóng: vùng bóng của mặt trời chỉ phủ quanh sông (core/lights.ts). */
   246	export function buildMountains() {
   247	  const mesh = new THREE.Mesh(mtGeometry(), MAT.mountain); mesh.name = 'mountains';
   248	  scene.add(mesh);
   249	}

