+  /* màu (sRGB) nướng vào đỉnh */
+  forestDark: 0x142e24, // rừng trong khe / sườn khuất (ước lượng theo ảnh)
+  forestMid: 0x28502a,  // rừng thường (ước lượng theo ảnh)
