+};
 const treesBase = {
   maxTris: { shadeCrown: 700, shadeTrunk: 150, palmCrown: 450, palmTrunk: 120, palmStatic: 260 },   // tam giác — trần mỗi hình (spec §6, quyết định của agent), unit test giữ
